from pathlib import Path

import streamlit as st


st.title("Reports")

st.write(
    "Access and download the financial analytics reports "
    "generated by the Nifty 100 Analytics platform."
)


PROJECT_ROOT = Path(__file__).resolve().parents[3]

OUTPUT_DIR = PROJECT_ROOT / "output"
REPORTS_DIR = PROJECT_ROOT / "reports"
RADAR_DIR = REPORTS_DIR / "radar_charts"


# -------------------------------------------------------------------
# Screener Report
# -------------------------------------------------------------------

st.divider()
st.subheader("Screener Report")

screener_file = OUTPUT_DIR / "screener_output.xlsx"

if screener_file.exists():

    st.success(
        "Screener workbook is available."
    )

    with open(screener_file, "rb") as file:
        st.download_button(
            label="Download Screener Workbook",
            data=file,
            file_name=screener_file.name,
            mime=(
                "application/vnd.openxmlformats-officedocument."
                "spreadsheetml.sheet"
            ),
        )

else:
    st.warning(
        "Screener workbook not found."
    )


