# -------------------------------------------------------------------
# Radar Charts
# -------------------------------------------------------------------

st.divider()
st.subheader("Company Radar Charts")

if RADAR_DIR.exists():

    radar_files = sorted(
        RADAR_DIR.glob("*_radar.png")
    )

    st.metric(
        "Available Radar Charts",
        len(radar_files),
    )

    if radar_files:

        selected_radar = st.selectbox(
            "Select Company",
            radar_files,
            format_func=lambda path: (
                path.stem.replace("_radar", "")
            ),
        )

        st.image(
            selected_radar,
            caption=selected_radar.stem.replace(
                "_radar",
                "",
            ),
            use_container_width=True,
        )

        with open(selected_radar, "rb") as file:
            st.download_button(
                label="Download Radar Chart",
                data=file,
                file_name=selected_radar.name,
                mime="image/png",
            )

else:
    st.warning(
        "Radar chart directory not found."
    )
